/* ===== V99: طباعة أرقام بسرعة ===== */
function numCanvas(n,tag,noFrame){
  const cv=document.createElement('canvas'); cv.width=640; cv.height=960;
  const x=cv.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,640,960);
  if(!noFrame){ x.strokeStyle='#000'; x.lineWidth=10; x.beginPath(); x.roundRect?x.roundRect(40,40,560,880,40):x.rect(40,40,560,880); x.stroke() }
  x.fillStyle='#000'; x.textAlign='center'; x.textBaseline='middle';
  const s=String(n); const sz=s.length<=1?560:s.length===2?440:s.length===3?300:220;
  x.font='900 '+sz+'px Cairo, sans-serif'; x.fillText(s,320,tag?500:480);
  if(tag){ x.font='800 64px Cairo, sans-serif'; x.fillText(tag,320,150) }
  return cv;
}
function numHTMLPrint(list,tag){
  const pages=list.map(n=>`<div class="pg"><img src="${numCanvas(n,tag).toDataURL('image/png')}"></div>`).join('');
  const old=document.getElementById('printFrame'); if(old) old.remove();
  const fr=document.createElement('iframe'); fr.id='printFrame';
  fr.style.cssText='position:fixed;left:-9999px;top:0;width:400px;height:600px;border:0;visibility:hidden';
  document.body.appendChild(fr);
  const d=fr.contentDocument;
  d.open(); d.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><style>@page{size:80mm 120mm;margin:0}body{margin:0}.pg{width:80mm;height:120mm;page-break-after:always}.pg:last-child{page-break-after:auto}.pg img{width:80mm;height:120mm;display:block}</style></head><body>${pages}</body></html>`); d.close();
  setTimeout(()=>{ try{ fr.contentWindow.focus(); fr.contentWindow.print() }catch(e){} },400);
}
/* طباعة سريعة: الرقم بخط الطابعة نفسها (بايتات قليلة جداً)، و"صافي" بس صورة صغيرة فوك */
function numJob(n,tag,cp){
  const enc=new TextEncoder(), s=String(n);
  const m=Math.max(1,Math.min(10,Math.floor(600/(32*s.length))));
  const w=32*m*s.length, h=48*m;
  const x=96+Math.round((640-w)/2), y=Math.round((960-h)/2)+(tag?40:0);
  let head;
  if(tag){
    const cv=document.createElement('canvas'); cv.width=640; cv.height=960;
    const c=cv.getContext('2d'); c.fillStyle='#fff'; c.fillRect(0,0,640,960); c.fillStyle='#000';
    c.textAlign='center'; c.textBaseline='middle'; c.font='800 72px Cairo, sans-serif'; c.fillText(tag,320,Math.max(90,y-90));
    const t=tsplBytes(cv,1), dec=new TextDecoder('latin1').decode(t), cut=dec.lastIndexOf('PRINT');
    head=t.slice(0,cut);
  } else head=enc.encode('SIZE 104 mm,120 mm\r\nGAP 3 mm,0 mm\r\nDENSITY 10\r\nCLS\r\n');
  const tail=enc.encode('TEXT '+x+','+y+',"5",0,'+m+','+m+',"'+s+'"\r\nPRINT 1,'+cp+'\r\n');
  const out=new Uint8Array(head.length+tail.length); out.set(head,0); out.set(tail,head.length);
  return out;
}
async function numPrint(){
  const a=Math.max(0,parseInt(document.getElementById('numFrom').value)||0);
  const b=Math.max(0,parseInt(document.getElementById('numTo').value)||0);
  const cp=Math.min(10,Math.max(1,parseInt(document.getElementById('numCopies').value)||1));
  const tag=document.getElementById('numTag').checked?'صافي':'';
  if(b<a){ toast('الرقم الأخير لازم يكون أكبر'); return }
  if(b-a+1>300){ toast('أكثر شي 300 رقم بالمرة'); return }
  const list=[]; for(let n=a;n<=b;n++) list.push(n);
  try{ localStorage.setItem('safi_numlast',String(b)); localStorage.setItem('safi_numcp',String(cp)); localStorage.setItem('safi_numsm',document.getElementById('numSmooth').checked?'1':'') }catch(e){}
  numClose();
  if(document.fonts&&document.fonts.load){ try{ await document.fonts.load('900 100px Cairo') }catch(e){} }
  if(typeof btChar!=='undefined'&&btChar&&btDev&&btDev.gatt.connected){
    try{
      toast('دا يطبع '+list.length+' رقم...');
      const smooth=document.getElementById('numSmooth').checked;
      const parts=list.map(n=>smooth?tsplBytes(numCanvas(n,tag,true),cp):numJob(n,tag,cp));
      let len=0; parts.forEach(p=>len+=p.length);
      const all=new Uint8Array(len); let o=0; parts.forEach(p=>{ all.set(p,o); o+=p.length });
      await btSend(all);
      toast('طبع ✓ من '+a+' إلى '+b); return;
    }catch(e){ alert('خطأ طباعة البلوتوث:\n'+(e.name||'')+'\n'+(e.message||'')) }
  }
  const rep=[]; list.forEach(n=>{ for(let i=0;i<cp;i++) rep.push(n) });
  numHTMLPrint(rep,tag);
}
function numOpen(){
  const last=+(localStorage.getItem('safi_numlast')||0);
  document.getElementById('numFrom').value=last?last+1:1;
  document.getElementById('numTo').value=(last?last:0)+20;
  document.getElementById('numCopies').value=+(localStorage.getItem('safi_numcp')||1);
  document.getElementById('numSmooth').checked=!!localStorage.getItem('safi_numsm');
  numCount(); document.getElementById('numOv').hidden=false;
  setTimeout(()=>document.getElementById('numFrom').focus(),50);
}
function numClose(){ document.getElementById('numOv').hidden=true }
function numCount(){
  const a=parseInt(document.getElementById('numFrom').value)||0, b=parseInt(document.getElementById('numTo').value)||0, cp=parseInt(document.getElementById('numCopies').value)||1;
  const n=b>=a?(b-a+1)*cp:0;
  document.getElementById('numInfo').textContent=n?('راح يطبع '+n+' استكر'):'الرقم الأخير لازم يكون أكبر';
  document.getElementById('numGo').disabled=!n;
}
document.getElementById('numBtn').addEventListener('click',numOpen);
document.getElementById('numCancel').addEventListener('click',numClose);
document.getElementById('numGo').addEventListener('click',numPrint);
document.getElementById('numOv').addEventListener('click',e=>{ if(e.target.id==='numOv') numClose() });
['numFrom','numTo','numCopies'].forEach(id=>document.getElementById(id).addEventListener('input',numCount));
document.querySelectorAll('#numQuick button').forEach(b=>b.addEventListener('click',()=>{
  const a=parseInt(document.getElementById('numFrom').value)||1; document.getElementById('numTo').value=a+(+b.dataset.n)-1; numCount();
}));
document.getElementById('numOv').addEventListener('keydown',e=>{ if(e.key==='Escape') numClose(); if(e.key==='Enter'&&!document.getElementById('numGo').disabled) numPrint() });

