<div class="num-ov" id="numOv" hidden>
  <div class="num-box" role="dialog" aria-modal="true" aria-labelledby="numT">
    <h3 id="numT">طباعة أرقام</h3>
    <div class="num-row">
      <label>من رقم<input id="numFrom" type="number" inputmode="numeric" min="0"></label>
      <label>إلى رقم<input id="numTo" type="number" inputmode="numeric" min="0"></label>
    </div>
    <div class="num-quick" id="numQuick" role="group" aria-label="عدد سريع"><button type="button" data-n="10">10 أرقام</button><button type="button" data-n="20">20</button><button type="button" data-n="50">50</button><button type="button" data-n="100">100</button></div>
    <div class="num-row">
      <label>نسخ لكل رقم<input id="numCopies" type="number" inputmode="numeric" min="1" max="10" value="1"></label>
      <label class="num-chk"><input type="checkbox" id="numTag"> اكتب "صافي" فوك الرقم</label>
    </div>
    <label class="num-chk num-sm"><input type="checkbox" id="numSmooth"> خط أنعم (أبطأ بالطباعة)</label>
    <div class="num-info" id="numInfo"></div>
    <div class="num-act"><button class="btn-dark" id="numGo">اطبع</button><button class="btn-sm" id="numCancel">إلغاء</button></div>
  </div>
</div>
    <button class="numbtn" id="numBtn">طباعة أرقام</button>
.numbtn{width:100%;min-height:40px;border-radius:10px;border:1px solid var(--line2,var(--line));background:transparent;color:var(--ink);font:inherit;font-size:13.5px;cursor:pointer;margin-bottom:8px}
.num-ov{position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:900;display:flex;align-items:center;justify-content:center;padding:16px}
.num-ov[hidden]{display:none}
.num-box{background:var(--paper,#16181c);border:1px solid var(--line);border-radius:18px;padding:22px;width:min(440px,100%);display:grid;gap:14px}
.num-box h3{margin:0;font-size:20px}
.num-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;align-items:end}
.num-row label{display:grid;gap:6px;font-size:14px;color:var(--mute,#9296A0)}
.num-row input[type=number]{min-height:56px;font-size:26px;font-weight:800;text-align:center;border-radius:12px}
.num-chk{display:flex !important;align-items:center;gap:8px;color:var(--ink) !important;cursor:pointer;min-height:56px}
.num-chk input{width:22px;height:22px;accent-color:#D4A24C}
.num-quick{display:flex;gap:6px}
.num-quick button{flex:1;min-height:40px;border-radius:10px;border:1px solid var(--line);background:transparent;color:var(--ink);font:inherit;cursor:pointer}
.num-sm{min-height:40px !important;font-size:14px;color:var(--mute,#9296A0) !important}
.num-info{font-size:15px;color:#D4A24C;text-align:center}
.num-act{display:grid;grid-template-columns:2fr 1fr;gap:10px}
.num-act button{min-height:52px;font-size:17px}
.num-act button:disabled{opacity:.4}
